<script lang="ts">
  import {createUserRow} from '../people.ts'
  import {place} from '../svelte/place.ts'
  import type {AccountController} from './controller.svelte.ts'

  let {c}: {c: AccountController} = $props()
  const view = $derived(c.accountView)
  let keyInput: HTMLInputElement, passwordInput: HTMLInputElement, bunkerInput: HTMLInputElement, connectLink: HTMLInputElement
  let name = $state(''), editName = $state(''), editPicture = $state('')

  // An attribute, not Svelte's autofocus helper: the dialog focuses it when shown.
  const autofocus = (node: HTMLElement) => { node.setAttribute('autofocus', '') }
  function ownRow(owner: string, displayName?: string) {
    const row = createUserRow(owner, {size: 44})
    const ownName = row.querySelector<HTMLElement>('.user-name')
    if (ownName && displayName) { delete ownName.dataset.personName; ownName.textContent = displayName }
    return row
  }
  function submit(event: SubmitEvent, action: () => unknown) { event.preventDefault(); action() }
  function linkDevice() { c.remoteOption.open = true; bunkerInput.value = ''; c.remoteForm.requestSubmit() }
  function editToggled(event: Event) {
    if ((event.currentTarget as HTMLDetailsElement).open && c.state.ownerPubkey) ({name: editName, picture: editPicture} = c.editDefaults())
  }
</script>

<button data-close class="dialog-close icon-button" aria-label="Close profile" onclick={() => c.account.close()}>×</button><h2 hidden={view.headingHidden}>{view.heading}</h2><div id="account-person">{#key c.accountVersion}{#if view.owner}<span hidden use:place={() => ownRow(view.owner, view.displayName)}></span>{/if}{/key}</div><p id="account-status" class="small muted" role="status">{c.accountStatus}</p><p id="account-error" class="error" role="alert">{c.accountError}</p>
<div id="account-login" hidden={view.loginHidden}><form id="account-create" class="profile-start" hidden={view.existing} onsubmit={e => submit(e, () => c.create(name))}><label for="account-name">Name <span class="muted">· optional</span></label><input id="account-name" bind:this={c.nameInput} bind:value={name} placeholder="Name" autocomplete="nickname" use:autofocus maxlength="80" disabled={view.busy}><button class="button primary" disabled={view.busy}>Continue</button></form><button id="account-existing-toggle" class="text-button profile-existing" hidden={view.existing} disabled={view.busy} onclick={() => c.showExisting()}>Existing profile</button>
<div id="account-existing" hidden={!view.existing}><button id="account-extension" class="button secondary" disabled={view.busy} onclick={() => c.useExtension()}>Browser extension</button><button id="account-link-device" class="button secondary" hidden={view.signingOnly} disabled={view.busy} onclick={linkDevice}>Link this device</button><details class="account-option" id="account-remote-option" bind:this={c.remoteOption}><summary>Remote signer</summary><form id="account-remote" bind:this={c.remoteForm} onsubmit={e => submit(e, () => c.connectRemote(bunkerInput.value))}><label for="account-bunker">Connection link <span class="muted">· optional</span></label><input id="account-bunker" bind:this={bunkerInput} placeholder="bunker://…" autocomplete="off"><button class="button secondary" disabled={view.busy}>Connect signer</button></form><div id="account-connect" hidden={c.connect.hidden}><p class="small muted">Approve this link on your other device.</p><input id="account-connect-link" bind:this={connectLink} value={c.connect.link} readonly aria-label="Signer connection link"><button id="account-copy-connect" class="text-button" onclick={() => navigator.clipboard.writeText(connectLink.value).catch(c.fail)}>Copy connection link</button><a id="account-open-connect" class="text-button" target="_blank" rel="noopener noreferrer" href={c.connect.href}>{c.connect.label}</a><button id="account-cancel-connect" class="text-button" onclick={() => c.controller?.abort()}>Cancel</button></div></details>
<details class="account-option" id="account-key-option" hidden={view.signingOnly}><summary>Private key</summary><form id="account-key-form" onsubmit={e => submit(e, () => c.loginWithKey(keyInput))}><label for="account-key">Private key</label><input id="account-key" bind:this={keyInput} type="password" placeholder="nsec…" autocomplete="off" spellcheck="false" required><button class="button secondary" disabled={view.busy}>Continue</button></form></details><button id="account-existing-back" class="text-button" hidden={view.signingOnly} disabled={view.busy} onclick={() => c.backToNew(keyInput)}>Back</button></div></div>
<form id="account-unlock" hidden={view.unlockHidden} onsubmit={e => submit(e, () => c.unlock(passwordInput))}><label for="account-password" hidden={view.passwordHidden}>Password</label><input id="account-password" bind:this={passwordInput} type="password" autocomplete="current-password" hidden={view.passwordHidden}><button class="button primary" disabled={view.busy}>Continue</button></form>
<div id="account-ready" hidden={view.readyHidden}><button id="account-open-invite" class="button primary" hidden={view.openInviteHidden} onclick={() => c.openInvite()}>Open private invitation</button><div class="account-actions"><button id="account-inbox" class="button primary" onclick={() => c.openInboxFromAccount()}>Messages</button><button id="account-profile" class="button secondary" onclick={() => c.openOwnProfile()}>View profile</button><button id="account-lock" class="text-button" onclick={() => c.lock()}>Lock</button></div><div id="posting-signer" hidden={view.postingSignerHidden}><p class="small muted">Connect a signer to post listings.</p><button id="posting-extension" class="button secondary" onclick={() => c.login(() => c.messaging.connectExtensionSigner())}>Use browser signer</button><button id="posting-remote" class="text-button" onclick={() => c.usePostingRemote()}>Use remote signer</button></div><details class="account-option" ontoggle={editToggled}><summary>Edit profile</summary><form id="account-edit-profile" onsubmit={e => submit(e, () => c.saveProfile(editName, editPicture))}><label>Name<input id="account-edit-name" bind:value={editName} maxlength="80" required autocomplete="nickname"></label><label>Photo link<input id="account-edit-picture" bind:value={editPicture} type="url" placeholder="https://…" autocomplete="off"></label><button class="button secondary" disabled={view.busy}>Save profile</button></form></details><details class="account-option"><summary>Linked devices</summary><div id="account-devices">{#each view.devices as device (device.pubkey)}<div class="device-row"><span>{device.label}</span>{#if device.revocable}<button class="text-button" onclick={() => c.revoke(device.pubkey)}>Revoke</button>{/if}</div>{/each}</div><p class="small muted">New messages reach your authorized devices. Earlier history is not copied automatically.</p></details><details class="account-option"><summary>Profile details</summary><button id="account-copy-id" class="text-button" onclick={() => c.copyId()}>Copy profile ID</button><button id="account-backup" class="text-button" hidden={view.backupHidden} onclick={() => c.copyBackup()}>Copy backup key</button><button id="account-invite" class="text-button" onclick={() => c.copyInvite()}>Copy private chat invitation</button></details></div>
